const $=id=>document.getElementById(id);let saved={};try{saved=JSON.parse(localStorage.getItem('tempo-settings')||'{}')}catch{}const valid=(v,f,max=3599)=>Number.isFinite(+v)&&+v>=1?Math.min(max,Math.round(+v)):f;let mode=saved.mode==='mmom'?'mmom':'interval',work=valid(saved.work,40),rest=valid(saved.rest,20),minutes=valid(saved.minutes,10,999),muted=!!saved.muted,presets=[];try{presets=JSON.parse(localStorage.getItem('tempo-presets')||'[]').filter(p=>Number.isInteger(p.work)&&p.work>0&&p.work<=3599&&Number.isInteger(p.rest)&&p.rest>0&&p.rest<=3599).slice(0,16)}catch{}
let running=false,phase='work',cycle=1,remaining=mode==='mmom'?60000:work*1000,deadline=0,lastSecond=null,finished=false,audio,wakeLock,installPrompt;
function toast(t){$('toast').textContent=t;$('toast').style.opacity=1;clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').style.opacity=0,3000)}function persist(){try{localStorage.setItem('tempo-settings',JSON.stringify({mode,work,rest,minutes,muted}))}catch{toast('Pamięć urządzenia jest niedostępna.')}}function fmt(s){s=Math.max(0,Math.ceil(s));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}function duration(){return mode==='mmom'?60000:(phase==='work'?work:rest)*1000}
function beep(long=false){if(muted||!audio)return;try{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime;o.frequency.value=long?560:1000;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.22,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+(long?.65:.13));o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+(long?.7:.15))}catch{}}async function unlock(){try{audio ||= new(window.AudioContext||window.webkitAudioContext)();await audio.resume()}catch{}}async function lock(){try{if('wakeLock'in navigator&&running)wakeLock=await navigator.wakeLock.request('screen')}catch{}}function release(){if(wakeLock){wakeLock.release().catch(()=>{});wakeLock=null}}
function render(){document.body.classList.toggle('rest',phase==='rest'&&mode==='interval');$('digits').textContent=fmt(remaining/1000);$('phase').textContent=finished?'KONIEC':mode==='mmom'?'MMoM':phase==='work'?'PRACA':'PRZERWA';$('cycle').textContent=String(cycle).padStart(2,'0');$('cycleTotal').textContent=mode==='mmom'?' / '+minutes:' / ∞';$('status').textContent=finished?'● TRENING UKOŃCZONY':running?'● TRENING TRWA':remaining===duration()&&cycle===1?'● GOTOWY DO STARTU':'● PAUZA';$('start').innerHTML=running?'<span>Ⅱ</span> Pauza':finished?'<span>↺</span> Jeszcze raz':'<span>▶</span> '+(remaining===duration()&&cycle===1?'Rozpocznij':'Kontynuuj');$('progress').style.width=Math.min(100,remaining/duration()*100)+'%';$('next').innerHTML=mode==='mmom'?(finished?'DOBRA ROBOTA':cycle===minutes?'NASTĘPNIE <b>KONIEC TRENINGU</b>':'NASTĘPNIE <b>MINUTA '+(cycle+1)+' · 01:00</b>'):'NASTĘPNIE <b>'+(phase==='work'?'PRZERWA · '+fmt(rest):'PRACA · '+fmt(work))+'</b>';$('modeLabel').textContent=mode==='mmom'?'MINUTA PO MINUCIE':'INTERWAŁY';document.title=(running?fmt(remaining/1000)+' · ':'')+'TEMPO — Timer treningowy';document.querySelectorAll('.fields input,.fields button,.tabs button,#presetList button:not(.delete)').forEach(b=>b.disabled=running)}
function reset(){running=false;finished=false;phase='work';cycle=1;remaining=mode==='mmom'?60000:work*1000;lastSecond=null;release();render()}function tick(){if(!running)return;const now=performance.now();remaining=deadline-now;let transitions=0;while(remaining<=0&&running){transitions++;if(mode==='mmom'){if(cycle>=minutes){remaining=0;running=false;finished=true;release();break}cycle++}else if(phase==='work')phase='rest';else{phase='work';cycle++}deadline+=duration();remaining=deadline-now;lastSecond=null}if(transitions)beep(true);const sec=Math.ceil(remaining/1000);if(running&&sec!==lastSecond){if(sec>=1&&sec<=5&&!transitions)beep();lastSecond=sec}render()}
$('start').onclick=async()=>{if(running){tick();running=false;release();render();return}await unlock();if(finished)reset();deadline=performance.now()+remaining;lastSecond=null;running=true;lock();tick()};$('reset').onclick=reset;
function sync(){$('work').value=work;$('rest').value=rest;$('minutes').value=minutes;for(const m of ['interval','mmom']){$(m).classList.toggle('active',mode===m);$(m).setAttribute('aria-selected',mode===m)}$('intervalSettings').hidden=mode!=='interval';$('mmomSettings').hidden=mode!=='mmom';$('modeDesc').textContent=mode==='interval'?'Praca i odpoczynek. W Twoim tempie.':'Nowa minuta. Nowy początek.';$('save').style.display=mode==='mmom'?'none':'flex';$('presets').hidden=mode==='mmom';$('sound').textContent=muted?'♪̸':'♫';$('sound').setAttribute('aria-label',muted?'Włącz dźwięk':'Wyłącz dźwięk');render()}
for(const m of ['interval','mmom'])$(m).onclick=()=>{mode=m;persist();reset();sync()};function change(id,v){if(running)return;const n=valid(v,id==='work'?work:id==='rest'?rest:minutes,id==='minutes'?999:3599);if(id==='work')work=n;else if(id==='rest')rest=n;else minutes=n;persist();reset();sync()}for(const id of ['work','rest','minutes'])$(id).onchange=e=>change(id,e.target.value);document.querySelectorAll('[data-field]').forEach(b=>b.onclick=()=>change(b.dataset.field,+$(b.dataset.field).value+ +b.dataset.delta));
function storePresets(){try{localStorage.setItem('tempo-presets',JSON.stringify(presets));return true}catch{toast('Nie można zapisać ustawień.');return false}}function renderPresets(){$('presetCount').textContent=presets.length+' / 16';$('presetList').replaceChildren();if(!presets.length){const p=document.createElement('p');p.className='empty';p.textContent='Zapisz pierwszy rytm swojego treningu.';$('presetList').append(p)}presets.forEach((p,i)=>{const div=document.createElement('div');div.className='preset';const load=document.createElement('button');load.textContent=String(p.work).padStart(2,'0')+'-'+String(p.rest).padStart(2,'0');load.title='Wczytaj '+p.work+' s pracy i '+p.rest+' s przerwy';load.onclick=()=>{work=p.work;rest=p.rest;mode='interval';persist();reset();sync();toast('Ustawienia wczytane')};const del=document.createElement('button');del.className='delete';del.textContent='×';del.setAttribute('aria-label','Usuń preset '+load.textContent);del.onclick=()=>{const old=[...presets];presets.splice(i,1);if(!storePresets())presets=old;renderPresets()};div.append(load,del);$('presetList').append(div)});render()}
$('save').onclick=()=>{if(presets.some(p=>p.work===work&&p.rest===rest)){toast('Te ustawienia są już zapisane.');$('presets').open=true;return}if(presets.length>=16){toast('Limit 16 ustawień. Usuń jeden z presetów.');$('presets').open=true;return}presets.push({work,rest});if(!storePresets()){presets.pop();return}renderPresets();$('presets').open=true;toast('Zapamiętano '+work+'-'+rest)};$('sound').onclick=()=>{muted=!muted;persist();unlock().then(()=>beep());sync()};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Pełny ekran jest dostępny po instalacji aplikacji.')}catch{toast('Pełny ekran jest niedostępny w tej przeglądarce.')}};
function clock(){$('clock').textContent=new Date().toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'});$('clock').dateTime=new Date().toISOString()}document.addEventListener('keydown',e=>{if(/INPUT|BUTTON|SUMMARY/.test(e.target.tagName)||$('installHelp').open||$('settingsDialog').open)return;if(e.code==='Space'){e.preventDefault();$('start').click()}if(e.key.toLowerCase()==='r')reset()});document.addEventListener('visibilitychange',()=>{if(!document.hidden){tick();lock()}});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else $('installHelp').showModal()};$('closeHelp').onclick=()=>$('installHelp').close();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{$('offlineInfo').textContent='Timer został przygotowany do pracy offline.'}).catch(()=>{$('offlineInfo').textContent='Tryb offline jest niedostępny w tej przeglądarce.'});setInterval(tick,80);setInterval(clock,1000);clock();sync();renderPresets();

function closeSettings(){$('settingsDialog').close();$('settingsOpen').focus()}
$('settingsOpen').onclick=()=>$('settingsDialog').showModal();
$('settingsClose').onclick=closeSettings;
$('settingsDone').onclick=closeSettings;
$('settingsDialog').addEventListener('click',e=>{if(e.target===$('settingsDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSettings()}});
